-- BEGIN AUTHORITATIVE REALYTICS SQL: 0016_identity_invitation_lifecycle.sql
-- Invite-first tenant onboarding and append-only identity access audit.
--
-- Plain invitation tokens never enter PostgreSQL.  A global, identity-role-only
-- hash index resolves an invitation's tenant before the transaction sets the
-- tenant-local RLS context.  The authoritative invitation and event history
-- remain tenant-scoped and FORCE RLS.

CREATE TABLE IF NOT EXISTS tenant_invitations (
    tenant_id              TEXT NOT NULL,
    invitation_id          TEXT NOT NULL,
    role                    TEXT NOT NULL,
    status                  TEXT NOT NULL DEFAULT 'pending',
    invited_email           TEXT,
    invited_issuer          TEXT,
    invited_subject         TEXT,
    token_hash              TEXT NOT NULL,
    issued_by_issuer        TEXT NOT NULL,
    issued_by_subject       TEXT NOT NULL,
    issued_at               TIMESTAMPTZ NOT NULL,
    expires_at              TIMESTAMPTZ NOT NULL,
    accepted_by_issuer      TEXT,
    accepted_by_subject     TEXT,
    accepted_at             TIMESTAMPTZ,
    revoked_at              TIMESTAMPTZ,
    revocation_reason       TEXT,
    created_at              TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    PRIMARY KEY (tenant_id, invitation_id),
    UNIQUE (token_hash),
    CONSTRAINT fk_tenant_invitations_tenant
        FOREIGN KEY (tenant_id)
        REFERENCES tenants(tenant_id) ON DELETE RESTRICT,
    CONSTRAINT ck_tenant_invitations_tenant_nonblank
        CHECK (btrim(tenant_id) <> ''),
    CONSTRAINT ck_tenant_invitations_id_nonblank
        CHECK (btrim(invitation_id) <> ''),
    CONSTRAINT ck_tenant_invitations_role
        CHECK (role IN (
            'admin', 'reviewer', 'analyst', 'viewer', 'legal_reviewer',
            'legal_counsel_approver', 'external_counsel',
            'compliance_officer'
        )),
    CONSTRAINT ck_tenant_invitations_status
        CHECK (status IN ('pending', 'accepted', 'revoked', 'expired')),
    CONSTRAINT ck_tenant_invitations_token_hash
        CHECK (token_hash ~ '^[0-9a-f]{64}$'),
    CONSTRAINT ck_tenant_invitations_issuer_subject_binding
        CHECK (
            (invited_issuer IS NULL AND invited_subject IS NULL)
            OR (
                btrim(invited_issuer) <> ''
                AND btrim(invited_subject) <> ''
            )
        ),
    CONSTRAINT ck_tenant_invitations_time_window
        CHECK (
            issued_at < expires_at
            AND created_at <= updated_at
            AND (accepted_at IS NULL OR accepted_at >= issued_at)
            AND (revoked_at IS NULL OR revoked_at >= issued_at)
        ),
    CONSTRAINT ck_tenant_invitations_acceptance
        CHECK (
            (status = 'accepted'
                AND accepted_by_issuer IS NOT NULL
                AND accepted_by_subject IS NOT NULL
                AND accepted_at IS NOT NULL
                AND revoked_at IS NULL)
            OR
            (status <> 'accepted'
                AND accepted_by_issuer IS NULL
                AND accepted_by_subject IS NULL
                AND accepted_at IS NULL)
        ),
    CONSTRAINT ck_tenant_invitations_revocation
        CHECK (
            (status = 'revoked' AND revoked_at IS NOT NULL)
            OR (status <> 'revoked' AND revoked_at IS NULL)
        )
);

CREATE INDEX IF NOT EXISTS idx_tenant_invitations_status_expiry
    ON tenant_invitations (tenant_id, status, expires_at, invitation_id);

-- This relation intentionally has no tenant_id column and no Data API grant.
-- Only the dedicated identity runtime role may use the hash to discover which
-- tenant RLS context must be set before reading tenant_invitations.
CREATE TABLE IF NOT EXISTS identity_invitation_token_index (
    token_hash          TEXT PRIMARY KEY,
    tenant_scope_key    TEXT NOT NULL,
    invitation_id       TEXT NOT NULL,
    status              TEXT NOT NULL DEFAULT 'pending',
    expires_at          TIMESTAMPTZ NOT NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    CONSTRAINT fk_identity_invitation_token
        FOREIGN KEY (tenant_scope_key, invitation_id)
        REFERENCES tenant_invitations(tenant_id, invitation_id)
        ON DELETE RESTRICT,
    CONSTRAINT ck_identity_invitation_token_hash
        CHECK (token_hash ~ '^[0-9a-f]{64}$'),
    CONSTRAINT ck_identity_invitation_token_tenant_nonblank
        CHECK (btrim(tenant_scope_key) <> ''),
    CONSTRAINT ck_identity_invitation_token_status
        CHECK (status IN ('pending', 'accepted', 'revoked', 'expired')),
    CONSTRAINT ck_identity_invitation_token_timestamp_order
        CHECK (created_at <= updated_at)
);

CREATE INDEX IF NOT EXISTS idx_identity_invitation_token_expiry
    ON identity_invitation_token_index (status, expires_at);

CREATE TABLE IF NOT EXISTS tenant_identity_access_events (
    tenant_id          TEXT NOT NULL,
    event_id           TEXT NOT NULL,
    event_type         TEXT NOT NULL,
    invitation_id      TEXT,
    actor_issuer       TEXT,
    actor_subject      TEXT,
    target_issuer      TEXT,
    target_subject     TEXT,
    event_payload      JSONB NOT NULL DEFAULT '{}'::jsonb,
    occurred_at        TIMESTAMPTZ NOT NULL,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    PRIMARY KEY (tenant_id, event_id),
    CONSTRAINT fk_tenant_identity_access_events_tenant
        FOREIGN KEY (tenant_id)
        REFERENCES tenants(tenant_id) ON DELETE RESTRICT,
    CONSTRAINT ck_tenant_identity_access_events_type_nonblank
        CHECK (btrim(event_type) <> ''),
    CONSTRAINT ck_tenant_identity_access_events_payload_object
        CHECK (jsonb_typeof(event_payload) = 'object')
);

CREATE INDEX IF NOT EXISTS idx_tenant_identity_access_events_time
    ON tenant_identity_access_events (
        tenant_id, occurred_at DESC, event_id
    );

